// Ownership and page positions belong to a character; sets reference the same items.
const INVENTORY_PAGE_SIZE=45;let inventorySelected=null,inventoryPage=0,inventoryDrag=null;
function inventoryItemHeight(it,d=data){if(!it)return 1;const entries={...window.ITEM_CATALOG,...(d.customCatalog||{})},entry=entries[it.catalogId]||Object.values(entries).find(e=>e.slot===it.slot&&normalized(e.label)===normalized(it.name)),path=entry?.image||('assets/'+iconName(it)+'.png'),height=window.ITEM_INVENTORY_SIZES?.[path];if(height)return height;if(['armor','costume'].includes(it.slot))return 2;if(it.slot==='weapon'||it.slot==='skin')return /arco|glaive|duas m[aã]os|two.hand/i.test(it.name)?3:/punha|adaga|garra/i.test(it.name)?1:2;return 1;}
function inventorySet(c){return c.sets[c===data.characters[ci]?si:0];}
function inventoryCells(index,height){if(!Number.isInteger(index)||index<0||index>=4500||Math.floor((index%45)/5)+height>9)return [];return Array.from({length:height},(_,i)=>index+i*5);}
function inventoryOccupancy(c=char(),ignore=[]){const grid=new Map(),excluded=new Set(ignore),equipped=new Set(Object.values(inventorySet(c)?.items||{}));c.inventory.forEach((id,index)=>{if(!id||excluded.has(id)||equipped.has(id))return;const it=item(id);for(const cell of inventoryCells(index,inventoryItemHeight(it)))grid.set(cell,{id,anchor:index});});return grid;}
function inventoryFits(index,height,grid){const cells=inventoryCells(index,height);return cells.length===height&&cells.every(i=>!grid.has(i));}
function inventoryFirstFit(height,grid,start=0,end=4500){for(let i=start;i<end;i++)if(inventoryFits(i,height,grid))return i;return -1;}
function normalizeInventoryLayout(c,d){const lookup=new Map(d.items.map(it=>[it.id,it])),equipped=new Set(Object.values(inventorySet(c)?.items||{})),entries=c.inventory.flatMap((id,index)=>id?[{id,index}]:[]),grid=new Map(),next=Array(c.inventory.length).fill(null);for(const {id,index} of entries.filter(x=>!equipped.has(x.id))){const height=inventoryItemHeight(lookup.get(id),d),anchor=inventoryFits(index,height,grid)?index:inventoryFirstFit(height,grid);if(anchor<0)throw Error('O inventário atingiu o limite de páginas.');next[anchor]=id;for(const cell of inventoryCells(anchor,height))grid.set(cell,{id,anchor});}for(const {id,index} of entries.filter(x=>equipped.has(x.id))){let anchor=!next[index]?index:next.findIndex(x=>!x);if(anchor<0)anchor=next.length;next[anchor]=id;}c.inventory=next;c.inventoryPages=Math.max(c.inventoryPages,Math.ceil((Math.max(0,...grid.keys())+1)/45));}
function normalizeInventories(d){const valid=new Set(d.items.map(i=>i.id)),claimed=new Set();for(const c of d.characters){const seen=new Set();c.inventory=(Array.isArray(c.inventory)?c.inventory:[]).slice(0,4500).map(id=>{if(typeof id!=='string'||!valid.has(id)||seen.has(id))return null;seen.add(id);claimed.add(id);return id;});for(const id of c.sets.flatMap(s=>Object.values(s.items)))if(valid.has(id)&&!seen.has(id)){c.inventory.push(id);seen.add(id);claimed.add(id);}c.inventoryPages=Math.max(4,Math.min(100,Number.isInteger(c.inventoryPages)?c.inventoryPages:4),Math.ceil(c.inventory.length/45));}const first=d.characters[0];for(const it of d.items)if(!claimed.has(it.id)){const empty=first.inventory.indexOf(null);if(empty>=0)first.inventory[empty]=it.id;else first.inventory.push(it.id);}for(const c of d.characters)normalizeInventoryLayout(c,d);}
function ownsInventoryItem(id,c=char()){return c.inventory?.includes(id)&&!!item(id);}
function inventoryEquipped(id){return Object.values(set().items).includes(id);}
function addInventoryReference(id,position){const it=item(id);if(!it)return;const c=char();c.inventory??=[];if(c.inventory.includes(id))return;const grid=inventoryOccupancy(c),height=inventoryItemHeight(it),anchor=inventoryFits(position,height,grid)?position:inventoryFirstFit(height,grid);if(anchor<0)throw Error('O inventário está cheio.');const displaced=c.inventory[anchor];if(displaced)c.inventory.push(displaced);c.inventory[anchor]=id;}
function equipInventoryItem(id,slot){const it=item(id);if(!char().sets.length||!ownsInventoryItem(id)||!it||it.slot!==slot||![...slots,...extra].some(e=>e[0]===slot)){toast('Este item só pode ser equipado no seu slot correspondente.');return false;}const previous=set().items[slot];if(previous===id)return true;const from=char().inventory.indexOf(id),old=char().inventory.indexOf(previous);if(previous){if(old>=0)char().inventory[old]=id;else char().inventory.push(id);char().inventory[from]=previous;}set().items[slot]=id;inventorySelected=null;hideTooltip();save();return true;}
function moveInventoryItem(id,index){if(!ownsInventoryItem(id)||!Number.isInteger(index)||index<0||index>=4500)return false;const c=char(),from=c.inventory.indexOf(id),target=inventoryOccupancy(c,[id]).get(index),other=target?.id;if(inventoryEquipped(id)&&other){if(item(other)?.slot===item(id)?.slot)return equipInventoryItem(other,item(id).slot);toast('Escolhe uma zona vazia para desequipar.');return false;}const grid=inventoryOccupancy(c,[id,other]),height=inventoryItemHeight(item(id)),otherHeight=other?inventoryItemHeight(item(other)):0,cells=inventoryCells(index,height),otherCells=other?inventoryCells(from,otherHeight):[];if(!inventoryFits(index,height,grid)||(other&&(!inventoryFits(from,otherHeight,grid)||cells.some(i=>otherCells.includes(i))))){toast('Não há espaço suficiente para esta troca.');return false;}const displaced=c.inventory[index];c.inventory[from]=null;if(other)c.inventory[target.anchor]=null;if(displaced&&displaced!==id&&displaced!==other)c.inventory.push(displaced);c.inventory[index]=id;if(other)c.inventory[from]=other;if(inventoryEquipped(id))delete set().items[item(id).slot];c.inventoryPages=Math.max(c.inventoryPages,Math.floor(index/45)+1);inventorySelected=null;hideTooltip();save();return true;}
function deleteInventoryItem(id){if(readonly||!ownsInventoryItem(id))return;for(const c of data.characters){c.inventory=c.inventory?.map(x=>x===id?null:x)||[];for(const s of c.sets)for(const k of Object.keys(s.items))if(s.items[k]===id)delete s.items[k];}data.items=data.items.filter(x=>x.id!==id);inventorySelected=null;}
function renderInventory(){const host=$('#inventory');if(!host)return;const c=char();if(inventorySelected?.character!==c.id||!ownsInventoryItem(inventorySelected?.id))inventorySelected=null;const pages=Math.max(4,c.inventoryPages,Math.ceil(c.inventory.length/45));inventoryPage=Math.max(0,Math.min(inventoryPage,pages-1));const selected=item(inventorySelected?.id),occupancy=inventoryOccupancy(c);host.innerHTML=`<div class="inventory-pages" role="group" aria-label="Páginas do inventário">${Array.from({length:pages},(_,i)=>`<button data-inventory-page="${i}" aria-pressed="${i===inventoryPage}">${i+1}</button>`).join('')}${!readonly&&pages<100?'<button data-inventory-add-page aria-label="Adicionar página">+</button>':''}</div><div class="inventory-grid">${Array.from({length:45},(_,i)=>{const index=inventoryPage*45+i,occupied=occupancy.has(index);return occupied?`<div class="inventory-cell" style="grid-column:${i%5+1};grid-row:${Math.floor(i/5)+1}" aria-hidden="true"></div>`:`<button class="inventory-cell" style="grid-column:${i%5+1};grid-row:${Math.floor(i/5)+1}" data-inventory-cell="${index}" aria-label="Célula vazia ${index+1}"></button>`;}).join('')}${c.inventory.flatMap((id,index)=>{const it=id&&!inventoryEquipped(id)?item(id):null;if(!it||Math.floor(index/45)!==inventoryPage)return [];const height=inventoryItemHeight(it),i=index%45;return [`<button class="inventory-item ${selected?.id===id?'selected':''}" style="grid-column:${i%5+1};grid-row:${Math.floor(i/5)+1} / span ${height}" data-inventory-cell="${index}" data-inventory-item="${esc(id)}" draggable="true" aria-label="${esc(it.name+' '+itemUpgrade(it)+' · '+height+' células')}">${equipmentIcon(it,it.slot)}<b class="upgrade">${esc(itemUpgrade(it))}</b></button>`];}).join('')}</div><p class="hint">${readonly?'Podes experimentar trocas nesta vista; não altera o perfil publicado.':'Arrasta para equipar ou trocar. Arrasta uma peça equipada para uma célula vazia para a retirar.'} Toca num item para ver os atributos e equipar.</p>${selected?`<div class="inventory-inspector">${bonusContent(selected)}<div class="inventory-item-actions"><button data-inventory-equip="${esc(selected.id)}" ${!c.sets.length?'disabled':''}>Equipar / trocar</button>${!readonly?`<button data-inventory-edit="${esc(selected.id)}">Editar</button><button class="danger" data-inventory-delete="${esc(selected.id)}">Eliminar</button>`:''}<button data-inventory-close>Fechar</button></div></div>`:''}`;for(const b of document.querySelectorAll('[data-slot]'))b.draggable=!!item(set().items[b.dataset.slot]);}
function newInventoryItem(position){if(readonly)return;openItemImport(position);}
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b)return;if(inventorySelected&&b.dataset.slot){e.stopImmediatePropagation();equipInventoryItem(inventorySelected.id,b.dataset.slot);return;}if(b.dataset.inventoryItem){e.stopImmediatePropagation();hideTooltip();inventorySelected={character:char().id,id:b.dataset.inventoryItem};renderInventory();return;}if(b.dataset.inventoryCell!==undefined&&!readonly){e.stopImmediatePropagation();newInventoryItem(Number(b.dataset.inventoryCell));return;}if(b.id==='addInventoryItem')newInventoryItem();if(b.dataset.inventoryPage!==undefined){inventoryPage=Number(b.dataset.inventoryPage);renderInventory();}if(b.hasAttribute('data-inventory-add-page')&&!readonly){char().inventoryPages++;inventoryPage=char().inventoryPages-1;save();}if(b.dataset.inventoryEquip)equipInventoryItem(b.dataset.inventoryEquip,item(b.dataset.inventoryEquip)?.slot);if(b.dataset.inventoryEdit&&!readonly)editSlot(item(b.dataset.inventoryEdit).slot,{inventory:true,id:b.dataset.inventoryEdit});if(b.dataset.inventoryDelete&&!readonly&&confirm('Eliminar este item do inventário e de todos os sets que o usam?')){deleteInventoryItem(b.dataset.inventoryDelete);save();}if(b.hasAttribute('data-inventory-close')){inventorySelected=null;renderInventory();}},true);
document.addEventListener('dragstart',e=>{const b=e.target.closest?.('[data-inventory-item],[data-slot]'),id=b?.dataset.inventoryItem||set().items[b?.dataset.slot];if(!b||!ownsInventoryItem(id)){e.preventDefault();return;}inventoryDrag={id,character:char().id};hideTooltip();e.dataTransfer?.setData('application/x-armory-item',id);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';document.body.classList.add('inventory-dragging');});
document.addEventListener('dragover',e=>{if(!inventoryDrag||inventoryDrag.character!==char().id)return;const b=e.target.closest?.('[data-slot],[data-inventory-cell],[data-inventory-page]');if(!b)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';});
document.addEventListener('drop',e=>{const drag=inventoryDrag;inventoryDrag=null;document.body.classList.remove('inventory-dragging');if(!drag||drag.character!==char().id)return;const b=e.target.closest?.('[data-slot],[data-inventory-cell],[data-inventory-page]');if(!b)return;e.preventDefault();if(b.dataset.slot)equipInventoryItem(drag.id,b.dataset.slot);else if(b.dataset.inventoryCell!==undefined)moveInventoryItem(drag.id,Number(b.dataset.inventoryCell));else if(b.dataset.inventoryPage!==undefined){inventoryPage=Number(b.dataset.inventoryPage);renderInventory();const empty=inventoryFirstFit(inventoryItemHeight(item(drag.id)),inventoryOccupancy(char(),[drag.id]),inventoryPage*45,(inventoryPage+1)*45);if(empty>=0)moveInventoryItem(drag.id,empty);else toast('Esta página está cheia.');}});
document.addEventListener('dragend',()=>{inventoryDrag=null;document.body.classList.remove('inventory-dragging');});
